import { flow, font, motion, neutral, radius, typeScale } from "./index";

function kebab(name: string): string {
  return name.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
}

function rem(px: number): string {
  return `${px / 16}rem`;
}

/**
 * Renders the tokens as a Tailwind v4 `@theme` block. The default
 * Tailwind palette is removed: only the DA colours exist as utilities
 * (`bg-surface`, `text-flow-request`, …).
 */
export function toThemeCss(): string {
  const lines: string[] = [
    "/* Generated by @nightprint/tokens (scripts/build-css.ts). Do not edit. */",
    "@theme {",
    "  --color-*: initial;",
  ];

  for (const [name, value] of Object.entries(neutral)) {
    lines.push(`  --color-${kebab(name)}: ${value};`);
  }
  for (const [name, value] of Object.entries(flow)) {
    lines.push(`  --color-flow-${name}: ${value};`);
  }

  lines.push("");
  for (const [name, f] of Object.entries(font)) {
    lines.push(`  --font-${name}: var(${f.cssVariable}, "${f.family}"), ${f.fallback};`);
  }

  lines.push("");
  for (const [name, style] of Object.entries(typeScale)) {
    lines.push(`  --text-${name}: ${rem(style.size)};`);
    lines.push(`  --text-${name}--line-height: ${style.lineHeight};`);
    lines.push(`  --text-${name}--letter-spacing: ${style.tracking}em;`);
    lines.push(`  --text-${name}--font-weight: ${style.weight};`);
  }

  lines.push("");
  for (const [name, px] of Object.entries(radius)) {
    lines.push(`  --radius-${name}: ${px}px;`);
  }

  lines.push("");
  lines.push(`  --ease-machine: cubic-bezier(${motion.ease.join(", ")});`);
  // `animate-enter`: what a step just brought (its caption, its log line) arrives instead of
  // swapping in: a short fade and a 4 px rise. Components pair it with motion-reduce:animate-none.
  lines.push(
    `  --animate-enter: enter ${motion.base}ms cubic-bezier(${motion.ease.join(", ")}) both;`,
  );
  // `animate-dash`: a dashed line runs along itself, the way a flow travels a pipe on a
  // plan view. One cycle moves two dash patterns of 0.45 plate units (see PlanView).
  lines.push("  --animate-dash: dash 1.4s linear infinite;");
  lines.push("  @keyframes dash {");
  lines.push("    to {");
  lines.push("      stroke-dashoffset: -0.9;");
  lines.push("    }");
  lines.push("  }");
  lines.push("  @keyframes enter {");
  lines.push("    from {");
  lines.push("      opacity: 0;");
  lines.push("      transform: translateY(4px);");
  lines.push("    }");
  lines.push("  }");
  lines.push("}");

  // Plex Mono capitals, +0.14 em: section titles, step numbers, breadcrumbs, the cartouche.
  lines.push("");
  lines.push("@utility mono-label {");
  lines.push("  font-family: var(--font-mono);");
  lines.push("  font-size: var(--text-label);");
  lines.push("  line-height: var(--text-label--line-height);");
  lines.push("  letter-spacing: var(--text-label--letter-spacing);");
  lines.push("  font-weight: var(--text-label--font-weight);");
  lines.push("  text-transform: uppercase;");
  lines.push("}");

  // `reveal`: a section's blocks rise into place as they scroll into view, driven by the
  // scroll itself, not a timer. Browsers without scroll timelines, and visitors who ask
  // for reduced motion, get the blocks in place at once.
  lines.push("");
  lines.push("@keyframes rise {");
  lines.push("  from {");
  lines.push("    opacity: 0;");
  lines.push("    transform: translateY(24px);");
  lines.push("  }");
  lines.push("}");
  lines.push("");
  lines.push("@utility reveal {");
  lines.push("  @media (prefers-reduced-motion: no-preference) {");
  lines.push("    @supports (animation-timeline: view()) {");
  lines.push("      animation: rise linear both;");
  lines.push("      animation-timeline: view();");
  lines.push("      animation-range: entry 0% entry 60%;");
  lines.push("    }");
  lines.push("  }");
  lines.push("}");

  return `${lines.join("\n")}\n`;
}
